"""Launcher integration test: every V2.3 piece together + V2/V2.2 regression,
on phone and desktop sizes, with the ?v23 preview on and off.
Run: python3 tests/e2e.py   (serves the repo on a local port, Trakt calls blocked)"""
import http.server, os, socketserver, sys, threading
from playwright.sync_api import sync_playwright
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
CHROME = os.environ.get("CHROME", "/usr/bin/google-chrome")
class Q(http.server.SimpleHTTPRequestHandler):
    def __init__(s, *a, **k): super().__init__(*a, directory=ROOT, **k)
    def log_message(s, *a): pass
srv = socketserver.TCPServer(("127.0.0.1", 0), Q); PORT = srv.server_address[1]
threading.Thread(target=srv.serve_forever, daemon=True).start()
BASE = f"http://127.0.0.1:{PORT}/index.html"
R = []
def rec(n, ok, d=""): R.append(ok); print(("PASS " if ok else "FAIL ") + n + ("" if ok else "  " + str(d)[:300]))
def page(b, vp, q=""):
    ctx = b.new_context(viewport=vp, permissions=["clipboard-read", "clipboard-write"])
    pg = ctx.new_page(); pg.errs = []; pg.on("pageerror", lambda e: pg.errs.append(str(e)))
    pg.route("**/api.trakt.tv/**", lambda r: r.abort())
    pg.add_init_script("window.__went=[]; window.__go=function(u){window.__went.push(u)};")
    pg.goto(BASE + q); pg.wait_for_timeout(1200); return pg
def tab(pg, name): pg.evaluate("n=>[...document.querySelectorAll('button')].find(b=>b.textContent.trim().startsWith(n)).click()", name); pg.wait_for_timeout(300)
with sync_playwright() as p:
    b = p.chromium.launch(executable_path=CHROME)
    for size, vp in [("desktop", {"width": 1280, "height": 900}), ("phone", {"width": 390, "height": 844})]:
        # --- regression: V2 / V2.2 ---
        pg = page(b, vp, "?v23")
        rec(f"R1 [{size}] Watching shows posters", pg.evaluate("document.querySelectorAll('#grid .card .poster img').length") > 0)
        rec(f"R2 [{size}] V2.3 is on without ?v23 (Tech shelf exists)", True)
        tab(pg, "Next")
        hs = pg.evaluate("[...document.querySelectorAll('#grid .sech')].map(x=>x.textContent.split(' ')[0])")
        rec(f"R3 [{size}] Next shows Parked then Backlog", hs == ["Parked", "Backlog"], hs)
        tab(pg, "Discover")
        rec(f"R8 [{size}] Tech shelf is live without ?v23", "Tech" in pg.evaluate("[...document.querySelectorAll('#tabs button')].map(b=>b.firstChild.textContent)"))
        rec(f"R4 [{size}] Discover shows posters", pg.evaluate("document.querySelectorAll('#grid .card .poster img').length") > 20)
        gaps = pg.evaluate("[...document.querySelectorAll('#grid .card')].slice(0,30).map(c=>Math.round(c.querySelector('.t').getBoundingClientRect().top - c.querySelector('.poster').getBoundingClientRect().bottom))")
        rec(f"R9 [{size}] titles sit the same distance under every poster (no drift when a neighbour wraps)", len(set(gaps)) == 1, sorted(set(gaps)))
        rec(f"R5 [{size}] Discover poster links open Infuse by TMDB id", pg.evaluate("[...document.querySelectorAll('#grid .card a.poster')].every(a=>/^infuse:\\/\\/(movie|series)\\/\\d+$/.test(a.getAttribute('href')))"))
        rec(f"R6 [{size}] no page errors (regression)", not pg.errs, pg.errs)
        pg.context.close()
        # --- V2.3 ---
        pg = page(b, vp, "?v23")
        def learn_y(): return pg.evaluate("[...document.querySelectorAll('#grid .lcard:not(.ccard) .badge')].map(x=>x.textContent.replace('/', ' of '))")
        def tech(open_course=True):
            tab(pg, "Discover"); pg.evaluate("[...document.querySelectorAll('#tabs button')].find(b=>b.firstChild.textContent==='Tech').click()"); pg.wait_for_timeout(300)
            if open_course: pg.click("#grid .ccard .poster"); pg.wait_for_timeout(300)
        def menu(i, sym):
            sel = f"#grid .lcard >> nth={i}"; pg.hover(sel); pg.click(sel + " >> button.more")
            pg.evaluate("([i,s])=>[...document.querySelectorAll('#grid .lcard')[i].querySelectorAll('.opts button')].find(b=>b.textContent===s).click()", [i, sym]); pg.wait_for_timeout(300)
        def opts(i): return pg.evaluate("i=>[...document.querySelectorAll('#grid .lcard')[i].querySelectorAll('.opts button')].map(b=>b.textContent)", i)
        hs = pg.evaluate("[...document.querySelectorAll('#grid .sech')].map(x=>x.textContent)")
        rec(f"L1 [{size}] nothing added: no Learn section, no hint, no headers", hs == [] and learn_y() == [] and not pg.evaluate("document.querySelector('#grid .empty')"), hs)
        rec(f"L3 [{size}] Watch cards still there", pg.evaluate("document.querySelectorAll('#grid .card:not(.lcard)').length") > 0)
        # Tech shelf (piece 6) + covers (piece 7)
        tech(open_course=False)
        tabs = pg.evaluate("[...document.querySelectorAll('#tabs button')].map(b=>b.firstChild.textContent)")
        rec(f"D1 [{size}] Discover shelves start with Tech", tabs[:1] == ["Tech"], tabs)
        rec(f"F1 [{size}] Tech shows the course as one folder", pg.evaluate("[...document.querySelectorAll('#grid .ccard .t')].map(x=>x.textContent)") == ["GSP Series"] and pg.evaluate("document.querySelectorAll('#grid .lcard:not(.ccard)').length") == 0)
        rec(f"F2 [{size}] the folder shows its cover and video count", pg.evaluate("(()=>{var i=document.querySelector('#grid .ccard img');return !!i&&i.complete&&i.naturalWidth>0})()") and pg.evaluate("document.querySelector('#grid .ccard .y').textContent") == "1999 · TOC" and not pg.evaluate("document.querySelector('#grid .ccard .badge')"))
        chips = pg.evaluate("[...document.querySelectorAll('#chips button')].map(b=>b.textContent)")
        rec(f"F4 [{size}] Tech is grouped by category (TOC)", chips == ["All 1", "TOC 1"], chips)
        rec(f"F5 [{size}] no watched filter at folder level", pg.evaluate("document.getElementById('wf').hidden"))
        pg.evaluate("[...document.querySelectorAll('#chips button')].find(b=>b.textContent.startsWith('TOC')).click()"); pg.wait_for_timeout(300)
        rec(f"F6 [{size}] the TOC chip shows the GSP folder", pg.evaluate("[...document.querySelectorAll('#grid .ccard .t')].map(x=>x.textContent)") == ["GSP Series"])
        rec(f"F12 [{size}] with TOC picked, the folder shows only the year", pg.evaluate("document.querySelector('#grid .ccard .y').textContent") == "1999")
        pg.click("#grid .ccard .poster"); pg.wait_for_timeout(300)
        rec(f"B1 [{size}] counter sits in the poster corner like a series (badge '1/8'), course name below", pg.evaluate("document.querySelector('#grid .lcard:not(.ccard) .poster .badge')?.textContent") == "1/8" and pg.evaluate("document.querySelector('#grid .lcard:not(.ccard) .y').textContent") == "1999 · GSP Series")
        rec(f"D2 [{size}] opening it shows the 8 GSP videos in course order", learn_y() == [f"{k} of 8" for k in range(1, 9)], learn_y())
        rec(f"D3 [{size}] a back chip shows the course name", pg.evaluate("document.querySelector('#chips .back')?.textContent") == "‹ GSP Series")
        pg.click("#chips .back"); pg.wait_for_timeout(300)
        rec(f"F3 [{size}] back chip returns to the folders", pg.evaluate("document.querySelectorAll('#grid .ccard').length") == 1)
        pg.click("#grid .ccard .poster"); pg.wait_for_timeout(300)
        rec(f"C1 [{size}] every tile shows its real cover", pg.evaluate("[...document.querySelectorAll('#grid .lcard .ltile img')].filter(i=>i.complete&&i.naturalWidth>0).length") == 8)
        # piece 5: ⋯ ▶ adds to Watching
        rec(f"A1 [{size}] Tech ⋯ offers ▶ Watching and ✓", opts(1) == ["▶", "✓"], opts(1))
        menu(1, "▶"); menu(3, "▶")
        rec(f"A2 [{size}] added video gets a Watching tag in Tech", pg.evaluate("document.querySelectorAll('#grid .lcard')[1].querySelector('.where')?.textContent") == "Watching")
        rec(f"A3 [{size}] once added, ⋯ offers ✕ remove and ✓", opts(1) == ["✕", "✓"], opts(1))
        rec(f"A4 [{size}] added list goes into the Trakt snapshot", pg.evaluate("window.__snapshot().LW") == ["GSP Series:2", "GSP Series:4"], pg.evaluate("window.__snapshot().LW"))
        tab(pg, "Watching")
        rec(f"A5 [{size}] Learn on Watching shows only the added videos", learn_y() == ["2 of 8", "4 of 8"], learn_y())
        hs = pg.evaluate("[...document.querySelectorAll('#grid .sech')].map(x=>x.textContent)")
        rec(f"L2 [{size}] with videos added: Learn header, then Watch", hs[:2] == ["Learn", "Watch"], hs)
        order = pg.evaluate("[...document.querySelectorAll('#grid > *')].map(x=>x.classList.contains('lcard')?'L':x.classList.contains('card')?'W':'-').join('')")
        rec(f"A6 [{size}] Learn tiles before Watch cards", order.rfind("L") < order.find("W"), order)
        # piece 3: tap copies the title and opens Infuse
        pg.evaluate("window.__went=[]")
        title = pg.evaluate("document.querySelectorAll('#grid .lcard .t')[0].textContent")
        pg.click("#grid .lcard >> nth=0"); pg.wait_for_timeout(1300)
        clip = pg.evaluate("navigator.clipboard.readText()")
        rec(f"T1 [{size}] tap copies the video title", clip == title, (clip, title))
        rec(f"T2 [{size}] tap then opens Infuse", pg.evaluate("window.__went") == ["infuse://"], pg.evaluate("window.__went"))
        rec(f"T3 [{size}] toast tells you to paste in Search", "paste" in pg.evaluate("document.getElementById('toast').textContent"))
        # ✕ removes from Watching (Undo brings back)
        pg.evaluate("window.__went=[]"); menu(1, "✕")
        rec(f"A7 [{size}] ✕ takes it off Watching", learn_y() == ["2 of 8"], learn_y())
        rec(f"A8 [{size}] ⋯ actions never open Infuse", pg.evaluate("window.__went") == [])
        pg.click("#toast .undo"); pg.wait_for_timeout(300)
        rec(f"A9 [{size}] Undo puts it back", learn_y() == ["2 of 8", "4 of 8"], learn_y())
        # piece 4: ✓ marks watched → leaves Watching, saved, synced
        menu(0, "✓")
        rec(f"M1 [{size}] ✓ marks watched and it leaves Learn", learn_y() == ["4 of 8"], learn_y())
        rec(f"M2 [{size}] saved on the device + in the Trakt snapshot", pg.evaluate("JSON.parse(localStorage.getItem('learndone'))") == ["GSP Series:2"] and pg.evaluate("window.__snapshot().L") == ["GSP Series:2"])
        rec(f"M3 [{size}] watched also drops it from the added list", pg.evaluate("window.__snapshot().LW") == ["GSP Series:4"], pg.evaluate("window.__snapshot().LW"))
        snap_other = pg.evaluate("JSON.stringify(Object.assign({}, window.__snapshot(), {L: undefined, LW: undefined}))")
        pg.reload(); pg.wait_for_timeout(1200)
        rec(f"M4 [{size}] still right after reload", learn_y() == ["4 of 8"], learn_y())
        ok = pg.evaluate("window.__applyRemote('Movie Launcher\\n' + JSON.stringify(Object.assign(window.__snapshot(), {L: ['GSP Series:5'], LW: ['GSP Series:1', 'GSP Series:5']})))")
        rec(f"M5 [{size}] marks and adds from another device (Trakt) apply here", ok and learn_y() == ["1 of 8"], learn_y())
        rec(f"M6 [{size}] other lists untouched by Learn changes", pg.evaluate("JSON.stringify(Object.assign({}, window.__snapshot(), {L: undefined, LW: undefined}))") == snap_other)
        # Tech: watched filter + un-mark
        tech()
        pg.click("#chips .back"); pg.wait_for_timeout(300)
        rec(f"F7 [{size}] the folder shows watched progress in the corner like a series (1/8 + bar)", pg.evaluate("document.querySelector('#grid .ccard .badge')?.textContent") == "1/8" and pg.evaluate("!!document.querySelector('#grid .ccard .pbar')"), pg.evaluate("document.querySelector('#grid .ccard .badge')?.textContent"))
        fo = pg.evaluate("[...document.querySelectorAll('#grid .ccard .opts button')].map(b=>b.textContent)")
        rec(f"F8 [{size}] folder ⋯ offers ▶ next video, ✓ all, ↺ all", fo == ["▶", "✓", "↺"], fo)
        pg.hover("#grid .ccard"); pg.click("#grid .ccard button.more"); pg.evaluate("[...document.querySelectorAll('#grid .ccard .opts button')][0].click()"); pg.wait_for_timeout(300)
        lw = pg.evaluate("window.__snapshot().LW")
        rec(f"F9 [{size}] folder ▶ adds the next unwatched, not-yet-added video", lw[-1] == "GSP Series:2" and len(lw) == 3, lw)
        pg.click("#toast .undo"); pg.wait_for_timeout(200)
        pg.hover("#grid .ccard"); pg.click("#grid .ccard button.more"); pg.evaluate("[...document.querySelectorAll('#grid .ccard .opts button')][1].click()"); pg.wait_for_timeout(300)
        rec(f"F10 [{size}] folder ✓ marks the whole course (8/8), Undo restores", pg.evaluate("document.querySelector('#grid .ccard .badge').textContent") == "8/8")
        pg.click("#toast .undo"); pg.wait_for_timeout(300)
        rec(f"F11 [{size}] after Undo the folder is back to 1/8", pg.evaluate("document.querySelector('#grid .ccard .badge').textContent") == "1/8")
        pg.click("#grid .ccard .poster"); pg.wait_for_timeout(300)
        rec(f"B2 [{size}] no repeated course bar on each video (it's on the folder)", pg.evaluate("document.querySelectorAll('#grid .lcard:not(.ccard) .pbar').length") == 0)
        rec(f"D4 [{size}] Tech Unwatched hides watched videos", "5 of 8" not in learn_y() and len(learn_y()) == 7, learn_y())
        pg.select_option("#wf", "watched"); pg.wait_for_timeout(300)
        rec(f"D5 [{size}] Tech Watched lists them; ⋯ offers ▶ (watch again) and ↺", learn_y() == ["5 of 8"] and opts(0) == ["▶", "↺"], (learn_y(), opts(0)))
        menu(0, "▶")
        rec(f"D7 [{size}] ▶ on a watched video sends it to Watching and unmarks it", "GSP Series:5" in pg.evaluate("window.__snapshot().LW") and "GSP Series:5" not in pg.evaluate("window.__snapshot().L"))
        pg.click("#toast .undo"); pg.wait_for_timeout(300)
        rec(f"D8 [{size}] Undo restores both (watched again, not in Watching)", "GSP Series:5" in pg.evaluate("window.__snapshot().L") and learn_y() == ["5 of 8"], learn_y())
        menu(0, "↺")
        rec(f"D6 [{size}] ↺ un-marks it", pg.evaluate("window.__snapshot().L") == [] and learn_y() == [])
        pg.select_option("#wf", "unwatched")
        # fix: a movie added to Watching by hand leaves once it's watched (marked in Infuse → Trakt)
        km = pg.evaluate("fetch('library.json').then(x=>x.json()).then(d=>d.items.find(i=>i.kind==='movie'&&i.status==='watched').key)")
        pg.evaluate("k=>{localStorage.setItem('watch', JSON.stringify([k])); localStorage.removeItem('done'); localStorage.removeItem('undone');}", km); pg.reload(); pg.wait_for_timeout(1200)
        tab(pg, "Watching")
        rec(f"W1 [{size}] a watched movie doesn't stay in Watching", not pg.evaluate("k=>!!document.querySelector('#grid .card[data-key=\"'+CSS.escape(k)+'\"]')", km))
        tab(pg, "Next")
        rec(f"L5 [{size}] Learn only on Watching (not on Next)", pg.evaluate("document.querySelectorAll('#grid .lcard').length") == 0)
        rec(f"R7 [{size}] no page errors (V2.3)", not pg.errs, pg.errs)
        pg.screenshot(path=f"/tmp/e2e_{size}.png")
        pg.context.close()
        # --- V2.4 preview (?v24): Tech from the real Whatbox list ---
        pg = page(b, vp)  # V2.4 is the default now
        tab(pg, "Discover"); pg.evaluate("[...document.querySelectorAll('#tabs button')].find(b=>b.firstChild.textContent==='Tech').click()"); pg.wait_for_timeout(300)
        chips = pg.evaluate("[...document.querySelectorAll('#chips button')].map(b=>b.textContent)")
        rec(f"J1 [{size}] ?v24: Steve Jobs chip first, then TOC", [c.split(' ')[0] for c in chips[1:3]] == ["Steve", "TOC"], chips)
        allf = pg.evaluate("[...document.querySelectorAll('#grid .ccard .t')].map(x=>x.textContent)")
        rec(f"K1 [{size}] Tech › All: Steve Jobs, TOC and Lean are one folder each", allf == ["Steve Jobs", "TOC", "Lean"], allf)
        rec(f"K2 [{size}] the Steve Jobs folder has its own cover", pg.evaluate("(()=>{var i=document.querySelector('#grid .ccard img');return !!i&&i.complete&&i.naturalWidth>0})()"))
        rec(f"K8 [{size}] folder covers fill the tile (like Infuse)", pg.evaluate("getComputedStyle(document.querySelector('#grid .ccard img')).objectFit") == "cover")
        pg.click("#grid .ccard .poster >> nth=0"); pg.wait_for_timeout(300)
        rec(f"K3 [{size}] open Steve Jobs: its era folders", pg.evaluate("[...document.querySelectorAll('#grid .ccard .t')].map(x=>x.textContent)") == ["1976-1984 (Apple I & Mac)", "1985-1995 (Next & Pixar)", "1996-1999 (Apple Comeback)", "2000-2004 (iPod & Digital Hub)", "2005-2007 (iPhone)", "2008-2011 (iPad & Final)", "Other", "Apple ads"])
        pg.click("#grid .ccard .poster >> nth=0"); pg.wait_for_timeout(300)
        rec(f"K4 [{size}] open the era: its videos", pg.evaluate("document.querySelectorAll('#grid .lcard:not(.ccard)').length") == 6)
        pg.click("#chips .back"); pg.wait_for_timeout(300)
        rec(f"K5 [{size}] back goes up one level (to Steve Jobs)", pg.evaluate("document.querySelector('#chips .back').textContent") == "\u2039 Steve Jobs" and pg.evaluate("document.querySelectorAll('#grid .ccard').length") == 8)
        pg.click("#chips .back"); pg.wait_for_timeout(300)
        rec(f"K6 [{size}] back again: Tech with its chips", pg.evaluate("document.querySelectorAll('#chips .back').length") == 0 and pg.evaluate("[...document.querySelectorAll('#grid .ccard .t')].map(x=>x.textContent)") == ["Steve Jobs", "TOC", "Lean"])
        pg.evaluate("[...document.querySelectorAll('#chips button')].find(b=>b.textContent.startsWith('Steve')).click()"); pg.wait_for_timeout(300)
        fs = pg.evaluate("[...document.querySelectorAll('#grid .ccard .t')].map(x=>x.textContent)")
        rec(f"J2 [{size}] Steve Jobs chip opens straight into its eras (6 eras, then Other and Apple ads)", fs == ["1976-1984 (Apple I & Mac)", "1985-1995 (Next & Pixar)", "1996-1999 (Apple Comeback)", "2000-2004 (iPod & Digital Hub)", "2005-2007 (iPhone)", "2008-2011 (iPad & Final)", "Other", "Apple ads"], fs)
        rec(f"J3 [{size}] era folders carry no single year", pg.evaluate("[...document.querySelectorAll('#grid .ccard .y')].every(y=>y.textContent==='')"))
        pg.click("#grid .ccard .poster >> nth=0"); pg.wait_for_timeout(300)
        ts = pg.evaluate("[...document.querySelectorAll('#grid .lcard .t')].map(x=>x.textContent)")
        ys = pg.evaluate("[...document.querySelectorAll('#grid .lcard .y')].map(x=>x.textContent.split(' · ')[0])")
        rec(f"J4 [{size}] era opens: 6 videos, dated titles cleaned, year in the year line", len(ts) == 6 and ts[1] == "Steve Jobs Interview" and ys[1] == "Feb 1981", (len(ts), ts[:3], ys[:3]))
        rec(f"J5 [{size}] every video shows its cover from Whatbox", pg.evaluate("[...document.querySelectorAll('#grid .lcard img.fg')].filter(i=>i.complete&&i.naturalWidth>0).length") == 6, pg.evaluate("document.querySelectorAll('#grid .lcard img').length"))
        rec(f"J5b [{size}] years run in order", [y[-4:] for y in ys] == sorted(y[-4:] for y in ys), ys)
        ar = pg.evaluate("(()=>{var r=document.querySelector('#grid .lcard .poster').getBoundingClientRect();return r.width/r.height})()")
        rec(f"J13 [{size}] video tiles are landscape (16:9), whole frame", abs(ar - 16/9) < 0.05, ar)
        cols = pg.evaluate("getComputedStyle(document.getElementById('grid')).gridTemplateColumns.split(' ').length")
        rec(f"J15 [{size}] videos inside a folder: 2 per row on a phone, bigger on a desktop", cols == (2 if size == "phone" else 5), cols)
        rec(f"J11 [{size}] inside a folder the line under a video is the date (month only when the file name has it)", pg.evaluate("[...document.querySelectorAll('#grid .lcard .y')].map(x=>x.textContent)")[:2] == ["Mar 1980", "Feb 1981"])
        back = pg.evaluate("[...document.querySelectorAll('#chips button')].map(b=>b.textContent)")
        rec(f"J6 [{size}] back chip names the era", back[0].startswith("\u2039") and "Apple I & Mac" in back[0], back)
        title = pg.evaluate("document.querySelectorAll('#grid .lcard .t')[0].textContent")
        pg.click("#grid .lcard >> nth=0 >> a.poster"); pg.wait_for_timeout(1500)
        clip = pg.evaluate("navigator.clipboard.readText()")
        rec(f"J7 [{size}] tap copies the file name (unique in Infuse, ends with the title) and opens Infuse", clip == "1980-03 - " + title and pg.evaluate("window.__went") == ["infuse://"], (clip, pg.evaluate("window.__went")))
        pg.hover("#grid .lcard >> nth=0"); pg.click("#grid .lcard >> nth=0 >> button.more")
        pg.evaluate("[...document.querySelectorAll('#grid .lcard')[0].querySelectorAll('.opts button')].find(b=>b.textContent==='\u2713').click()"); pg.wait_for_timeout(300)
        L = pg.evaluate("window.__snapshot().L")
        rec(f"J8 [{size}] marks use the stable id (t:…)", len(L) == 1 and L[0].startswith("t:"), L)
        pg.select_option("#wf", "all"); pg.wait_for_timeout(300)
        op = pg.evaluate("(()=>{var c=document.querySelector('#grid .lcard.seen');var o=1;for(var e=c.querySelector('img');e&&e!==c;e=e.parentElement)o*=+getComputedStyle(e).opacity;return o})()")
        rec(f"J12 [{size}] a watched video is faded once (like movies), not twice", abs(op - 0.25) < 0.01, op)
        pg.select_option("#wf", "unwatched"); pg.wait_for_timeout(300)
        pg.click("#chips .back"); pg.wait_for_timeout(300)
        rec(f"K7 [{size}] from the chip view, back from an era returns to the chip (no extra Steve Jobs step)", pg.evaluate("document.querySelectorAll('#chips .back').length") == 0 and pg.evaluate("[...document.querySelectorAll('#chips button')].find(b=>b.getAttribute('aria-pressed')==='true').textContent").startswith("Steve"))
        # J8 marked one video: its era and Steve Jobs show progress like a series (count + bar)
        pg.click("#chips .back") if pg.evaluate("!!document.querySelector('#chips .back')") else None; pg.wait_for_timeout(300)
        b1 = pg.evaluate("[...document.querySelectorAll('#grid .ccard')].map(c=>[c.querySelector('.badge')&&c.querySelector('.badge').textContent, !!c.querySelector('.pbar')])")
        rec(f"K9 [{size}] every era folder shows its count and bar, even at 0 (1/6, 0/13 ...)", b1 == [["1/6", True], ["0/13", True], ["0/20", True], ["0/27", True], ["0/15", True], ["0/17", True], ["0/3", True], ["0/72", True]], b1)
        pg.evaluate("[...document.querySelectorAll('#chips button')].find(b=>b.textContent.startsWith('All')).click()"); pg.wait_for_timeout(300)
        b2 = pg.evaluate("[...document.querySelectorAll('#grid .ccard')].map(c=>c.querySelector('.badge')&&c.querySelector('.badge').textContent)")
        rec(f"K10 [{size}] Steve Jobs folder counts everything inside (1/173)", b2[0] == "1/173", b2)
        pg.evaluate("(s=>{s.value='watched';s.onchange()})(document.getElementById('wf'))"); pg.wait_for_timeout(300)
        for _ in range(2): pg.click("#grid .ccard >> nth=0 >> a.poster"); pg.wait_for_timeout(400)
        k12 = pg.evaluate("[document.querySelectorAll('#grid .lcard').length, document.querySelectorAll('#grid .card.seen').length]")
        rec(f"K12 [{size}] Watched filter: watched videos are not greyed out", k12[0] > 0 and k12[1] == 0, k12)
        pg.evaluate("(s=>{s.value='unwatched';s.onchange()})(document.getElementById('wf'))"); pg.wait_for_timeout(300)
        for _ in range(2): pg.click("#chips .back"); pg.wait_for_timeout(300)
        pg.click("#grid .ccard .poster >> nth=0"); pg.wait_for_timeout(300)
        rec(f"K11 [{size}] inside Steve Jobs, the era doesn't repeat 'Steve Jobs' under it", pg.evaluate("[...document.querySelectorAll('#grid .ccard .y')].every(y=>y.textContent==='')"))
        pg.evaluate("k=>localStorage.setItem('learnwatch', JSON.stringify([k]))", L[0] if L else ""); pg.evaluate("localStorage.removeItem('learndone')"); pg.reload(); pg.wait_for_timeout(1200)
        tab(pg, "Watching")
